package app.dayflow;
import android.Manifest;import android.content.*;import android.content.pm.*;import android.provider.*;import android.widget.*;import com.google.android.material.materialswitch.MaterialSwitch;import com.google.android.material.textfield.TextInputEditText;import org.json.*;import java.util.*;

/** Unified notification/SMS sources, observed conversations and local regex rules. */
final class GroupCaptureSettings {
 private static void toggle(MainActivity a,LinearLayout page,String label,String key,boolean fallback){MaterialSwitch control=new MaterialSwitch(a);control.setText(label);control.setChecked(a.prefs.getBoolean(key,fallback));control.setOnCheckedChangeListener((v,on)->a.prefs.edit().putBoolean(key,on).apply());page.addView(control);}
 static void show(MainActivity a){LinearLayout page=a.fullPage("通知收集",a::home);page.addView(Ui.text(a,"通知与短信统一收集",23,true));toggle(a,page,"启用信息收集","capture",false);page.addView(Ui.button(a,"系统通知访问授权",false,()->a.startActivity(new Intent(Settings.ACTION_NOTIFICATION_LISTENER_SETTINGS))));toggle(a,page,"收集所有内容（不要求日程关键词）","capture_all_messages",false);toggle(a,page,"收集所有应用的通知","capture_all_apps",false);page.addView(Ui.button(a,"选择收集的软件",false,()->apps(a,"")));page.addView(Ui.help(a,"所有内容仍受应用、会话和正则规则筛选。应用自己的通知、汇总通知和常驻状态不收集。仅能取得系统实际发出的通知。"));
  page.addView(Ui.text(a,"短信",18,true));toggle(a,page,"同时接收新短信","capture_sms",false);page.addView(Ui.button(a,"授权接收新短信",false,()->{a.prefs.edit().putBoolean("capture",true).putBoolean("capture_sms",true).apply();String pkg=Telephony.Sms.getDefaultSmsPackage(a);if(pkg!=null){Set<String> selected=CaptureRules.packages(a);selected.add(pkg);a.prefs.edit().putString("packages",String.join(",",selected)).apply();}if(a.checkSelfPermission(Manifest.permission.RECEIVE_SMS)!=PackageManager.PERMISSION_GRANTED)a.requestPermissions(new String[]{Manifest.permission.RECEIVE_SMS},202);else a.message("已授权");}));page.addView(Ui.help(a,"取件码和话费自动附加结构化信息，仍为待确认；开启全部内容后也可保留其他短信。不读取历史短信。"));
  page.addView(Ui.text(a,"会话与群聊",18,true));toggle(a,page,"仅收集选中的聊天会话","capture_group_filter",!a.prefs.getString("capture_groups","").trim().isEmpty());page.addView(Ui.button(a,"从已发现会话中选择",false,()->groups(a)));page.addView(Ui.help(a,"先启用收集并接收一些QQ、微信或TIM通知，系统提供的会话名会出现在列表。部分通知只提供标题，可能包括私聊，请核对后选择。筛选只影响后续收集，不删除已收集信息。"));
  TextInputEditText include=Ui.field(a,page,"正则：命中任意一行才收集（空为不限）",a.prefs.getString("capture_regex_include",""),true),exclude=Ui.field(a,page,"正则：命中任意一行则排除",a.prefs.getString("capture_regex_exclude",""),true);page.addView(Ui.help(a,"使用RE2正则，支持 |、分组、数量词、(?i)忽略大小写；不支持回溯引用或环视。例如：会议|讲座|报名；排除：广告|优惠券。排除优先。"));TextInputEditText sample=Ui.field(a,page,"本地规则预览文本（不会发送AI）","",true);page.addView(Ui.button(a,"预览正则结果",false,()->{try{CaptureRules.validate(include.getText().toString());CaptureRules.validate(exclude.getText().toString());String value=sample.getText().toString();boolean allow=include.getText().toString().trim().isEmpty(),deny=false;for(String line:include.getText().toString().split("\\R"))if(!line.trim().isEmpty()&&com.google.re2j.Pattern.compile(line.trim()).matcher(value).find())allow=true;for(String line:exclude.getText().toString().split("\\R"))if(!line.trim().isEmpty()&&com.google.re2j.Pattern.compile(line.trim()).matcher(value).find())deny=true;a.message(deny?"会被排除":allow?"通过正则筛选；还需符合应用与会话设置":"未命中包含规则");}catch(Exception e){a.message("规则无效："+e.getMessage());}}));page.addView(Ui.button(a,"保存正则筛选器",true,()->{try{CaptureRules.validate(include.getText().toString());CaptureRules.validate(exclude.getText().toString());a.prefs.edit().putString("capture_regex_include",include.getText().toString()).putString("capture_regex_exclude",exclude.getText().toString()).apply();a.message("规则已保存");}catch(Exception e){a.message("未保存："+e.getMessage());}}));
 }
 static void apps(MainActivity a,String query){apps(a,query,0);}
 static void apps(MainActivity a,String query,int offset){LinearLayout page=a.fullPage("选择收集的软件",()->show(a));TextInputEditText search=Ui.field(a,page,"搜索应用名称或包名",query,false);page.addView(Ui.button(a,"搜索",false,()->apps(a,search.getText().toString())));Map<String,String> entries=new TreeMap<>();try{Intent launcher=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER);for(ResolveInfo info:a.getPackageManager().queryIntentActivities(launcher,0))entries.put(info.activityInfo.packageName,info.loadLabel(a.getPackageManager()).toString());JSONObject known=new JSONObject(a.prefs.getString("capture_known_apps","{}"));Iterator<String> keys=known.keys();while(keys.hasNext()){String pkg=keys.next();entries.put(pkg,known.optString(pkg));}String sms=Telephony.Sms.getDefaultSmsPackage(a);if(sms!=null)entries.put(sms,"短信 · "+sms);for(String pkg:CaptureRules.packages(a))entries.putIfAbsent(pkg,pkg);}catch(Exception ignored){}Set<String> selected=CaptureRules.packages(a);int matched=0,displayed=0;for(Map.Entry<String,String> item:entries.entrySet()){String pkg=item.getKey();if(pkg.equals(a.getPackageName())||pkg.startsWith("app.dayflow.")||!(item.getValue()+pkg).toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT)))continue;if(matched++<offset)continue;if(displayed++>=40)continue;com.google.android.material.checkbox.MaterialCheckBox box=new com.google.android.material.checkbox.MaterialCheckBox(a);box.setText(item.getValue()+"\n"+pkg);box.setChecked(selected.contains(pkg));box.setOnCheckedChangeListener((v,on)->{if(on)selected.add(pkg);else selected.remove(pkg);a.prefs.edit().putString("packages",String.join(",",selected)).putBoolean("capture_all_apps",false).apply();});page.addView(box);}if(offset>0)page.addView(Ui.button(a,"上一页",false,()->apps(a,query,Math.max(0,offset-40))));if(matched>offset+40)page.addView(Ui.button(a,"下一页",false,()->apps(a,query,offset+40)));page.addView(Ui.help(a,"选择即时保存，并切换为仅收集选中应用。列表包括可启动应用和已发现的通知来源。"));}
 static void groups(MainActivity a){final TextInputEditText[] manualHolder={null};LinearLayout page=a.fullPage("已发现会话",()->show(a));Set<String> selected=new LinkedHashSet<>(Arrays.asList(a.prefs.getString("capture_groups","").split("\\R")));try{JSONObject known=new JSONObject(a.prefs.getString("capture_known_groups","{}"));if(known.length()==0)page.addView(Ui.help(a,"尚未发现会话。先启用通知访问和收集，在聊天应用接收一些通知后再回来。"));Iterator<String> keys=known.keys();while(keys.hasNext()){String key=keys.next();JSONObject item=known.getJSONObject(key);com.google.android.material.checkbox.MaterialCheckBox box=new com.google.android.material.checkbox.MaterialCheckBox(a);box.setText(item.optString("name")+" · "+item.optString("label"));String alias=(item.optString("package").equals("com.tencent.mm")?"微信":item.optString("package").equals("com.tencent.tim")?"TIM":"QQ")+"|"+item.optString("name");box.setChecked(selected.contains(key)||selected.contains(item.optString("name"))||selected.contains(alias));box.setOnCheckedChangeListener((v,on)->{selected.remove(item.optString("name"));selected.remove(alias);selected.remove("");if(on)selected.add(key);else selected.remove(key);a.prefs.edit().putString("capture_groups",String.join("\n",selected)).putBoolean("capture_group_filter",true).apply();if(manualHolder[0]!=null)manualHolder[0].setText(String.join("\n",selected));});page.addView(box);}}catch(Exception e){a.message(e.getMessage());}TextInputEditText manual=Ui.field(a,page,"手动会话规则（每行一个，可写 QQ|群名）",a.prefs.getString("capture_groups",""),true);manualHolder[0]=manual;page.addView(Ui.button(a,"保存手动规则",false,()->{a.prefs.edit().putString("capture_groups",manual.getText().toString().trim()).putBoolean("capture_group_filter",true).apply();a.message("会话规则已保存");}));}
}
